from typing import Annotated
from fastapi import Depends, FastAPI
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_authorization_whitespace():
    # Test case 1: Single space (correct)
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 2: Multiple spaces
    response = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 3: Trailing whitespace
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

if __name__ == "__main__":
    try:
        test_authorization_whitespace()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

steps.message:
The issue was that `get_authorization_scheme_param` in `fastapi/security/utils.py` did not strip leading and trailing whitespace from the extracted credential parameter, which violates RFC 6750 and can lead to authentication failures.

I have modified `fastapi/security/utils.py` to call `.strip()` on the `param` before returning it.

```python
def get_authorization_scheme_param(
    authorization_header_value: Optional[str],
) -> tuple[str, str]:
    if not authorization_header_value:
        return "", ""
    scheme, _, param = authorization_header_value.partition(" ")
    return scheme, param.strip()
```

I verified the fix with a reproduction script that tested single space, multiple spaces, and trailing whitespace in the `Authorization` header, and all cases now return the correctly stripped credentials. I also ran `tests/test_security_http_bearer.py` to ensure no regressions were introduced.
